+*/
+
+#include "model/wallpapersearch.h"
+
+#include <QSignalSpy>
+#include <QTest>
+#include <QUrl>
+
+class WallpaperSearchTest : public QObject
+{
+    Q_OBJECT
+
+private Q_SLOTS:
+    void matching_data()
+    {
+        QTest::addColumn<QString>("locale");
+        QTest::addColumn<QString>("name");
+        QTest::addColumn<QString>("fileName");
+        QTest::addColumn<QString>("query");
+        QTest::addColumn<bool>("matches");
+
+        QTest::newRow("display name") << "en_US" << "Mountain lake" << "other.png" << "MOUNTAIN" << true;
+        QTest::newRow("decoded filename") << "en_US" << "Other" << "City% #夜.png" << "% #夜.PNG" << true;
+        QTest::newRow("package directory") << "en_US" << "Evening Glow" << "EveningBundle/" << "eveningbundle" << true;
+        QTest::newRow("trimmed") << "en_US" << "Mountain" << "other.png" << "  mountain  " << true;
+        QTest::newRow("blank") << "en_US" << "Mountain" << "other.png" << "   " << true;
+        QTest::newRow("literal regex") << "en_US" << "Mountain" << "other.png" << ".*" << false;
+        QTest::newRow("Turkish dotless I") << "tr_TR" << "IŞIK" << "other.png" << "ışık" << true;
+        QTest::newRow("Turkish dotted I") << "tr_TR" << "İzmir" << "other.png" << "izmir" << true;
+        QTest::newRow("Turkish distinct I") << "tr_TR" << "Işık" << "other.png" << "işik" << false;
+        QTest::newRow("English distinct I") << "en_US" << "IŞIK" << "other.png" << "ışık" << false;
+        QTest::newRow("Greek sigma") << "el_GR" << "ΟΣ" << "other.png" << "ος" << true;
+        QTest::newRow("German sharp S") << "de_DE" << "Straße" << "other.png" << "STRAẞE" << true;
+        QTest::newRow("canonical equivalence") << "en_US" << "Café" << "other.png" << QString::fromUtf8("cafe\xcc\x81") << true;
+        QTest::newRow("accent distinction") << "en_US" << "Café" << "other.png" << "cafe" << false;
+        QTest::newRow("Thai punctuation retained") << "th_TH" << "a-b" << "other.png" << "ab" << false;
+        QTest::newRow("Thai brackets retained") << "th_TH" << "[1].png" << "other.png" << "1png" << false;
+        QTest::newRow("Thai literal punctuation") << "th_TH" << "x.*y" << "other.png" << ".*" << true;
+    }
+
+    void matching()
+    {
+        QFETCH(QString, locale);
+        QFETCH(QString, name);
+        QFETCH(QString, fileName);
+        QFETCH(QString, query);
+        QFETCH(bool, matches);
+        const QLocale previousLocale;
+        QLocale::setDefault(QLocale(locale));
+        WallpaperSearch search;
+        search.setSearchText(query);
+        const bool result = search.matches(name, QUrl::fromLocalFile(QStringLiteral("/wallpapers/") + fileName));
+        QLocale::setDefault(previousLocale);
+        QCOMPARE(result, matches);
+    }
+
+    void repeatedTargets()
+    {
+        WallpaperSearch search;
+        QSignalSpy querySpy(&search, &WallpaperSearch::searchTextChanged);
+        for (int repetition = 0; repetition < 30; ++repetition) {
+            search.setSearchText(QStringLiteral("lake"));
+            QVERIFY(search.matches(QStringLiteral("Lake"), QUrl()));
+            QVERIFY(!search.matches(QStringLiteral("Sunrise"), QUrl()));
+            QVERIFY(search.matches(QStringLiteral("Mountain lake"), QUrl()));
+            QVERIFY(search.matches(QStringLiteral("Other"), QUrl::fromLocalFile(QStringLiteral("/wallpapers/lake.png"))));
+            search.setSearchText(QStringLiteral("sun"));
+            QVERIFY(!search.matches(QStringLiteral("Lake"), QUrl()));
+            QVERIFY(search.matches(QStringLiteral("Sunrise"), QUrl()));
+        }
+        QCOMPARE(querySpy.count(), 60);
+        search.setSearchText(QStringLiteral("sun"));
+        QCOMPARE(querySpy.count(), 60);
+        search.setSearchText(QString());
+        QVERIFY(search.matches(QString(), QUrl()));
+    }
+};
+
+QTEST_GUILESS_MAIN(WallpaperSearchTest)
+
+#include "test_wallpapersearch.moc"
