+#include "wallpapersearch.h"
+
+#include "debug.h"
+
+#include <unicode/tblcoll.h>
+
+namespace
+{
+icu::UnicodeString unicodeString(const QString &text)
+{
+    return icu::UnicodeString(reinterpret_cast<const UChar *>(text.utf16()), text.size());
+}
+} // namespace
+
+WallpaperSearch::WallpaperSearch(QObject *parent)
+    : QObject(parent)
+{
+}
+
+QString WallpaperSearch::searchText() const
+{
+    return m_searchText;
+}
+
+void WallpaperSearch::setSearchText(const QString &text)
+{
+    const QLocale locale;
+    if (m_searchText == text && m_locale == locale) {
+        return;
+    }
+
+    m_searchText = text;
+    m_pattern = text.trimmed();
+    m_locale = locale;
+    m_search.reset();
+    if (!m_pattern.isEmpty()) {
+        UErrorCode error = U_ZERO_ERROR;
+        m_search = std::make_unique<icu::StringSearch>(unicodeString(m_pattern),
+                                                       unicodeString(QStringLiteral(" ")),
+                                                       icu::Locale(locale.name().toLatin1().constData()),
+                                                       nullptr,
+                                                       error);
+        if (U_SUCCESS(error)) {
+            auto *collator = m_search->getCollator();
+            collator->setStrength(icu::Collator::SECONDARY);
+            collator->setAttribute(UCOL_NORMALIZATION_MODE, UCOL_ON, error);
+            // Some locales ignore punctuation by default. Filenames must still match
+            // literally.
+            collator->setAttribute(UCOL_ALTERNATE_HANDLING, UCOL_NON_IGNORABLE, error);
+            m_search->reset();
+        }
+        if (U_FAILURE(error)) {
+            qCWarning(IMAGEWALLPAPER) << "Could not create wallpaper search:" << u_errorName(error);
+            m_search.reset();
+        }
+    }
+    Q_EMIT searchTextChanged();
+}
+
+bool WallpaperSearch::matchesText(const QString &text) const
+{
+    if (text.isEmpty()) {
+        return false;
+    }
+    if (!m_search) {
+        return text.contains(m_pattern, Qt::CaseInsensitive);
+    }
+    UErrorCode error = U_ZERO_ERROR;
+    // ICU keeps the supplied buffer, including for short strings stored inline.
+    m_target = unicodeString(text);
+    m_search->setText(m_target, error);
+    return U_SUCCESS(error) && m_search->first(error) != USEARCH_DONE && U_SUCCESS(error);
+}
+
+bool WallpaperSearch::matches(const QString &name, const QUrl &source) const
+{
+    return m_pattern.isEmpty() || matchesText(name) || matchesText(source.adjusted(QUrl::StripTrailingSlash).fileName());
+}
